mapper.select:
SELECT * FROM biz_practical_ai_job
WHERE teacher_user_id=#{teacherUserId} AND lesson_id=#{lessonId} AND question_id=#{questionId}
  AND entry_year=#{entryYear} AND class_code=#{classCode}
  AND job_status IN ('PENDING','RUNNING','PAUSED','CANCEL_REQUESTED')
ORDER BY job_id DESC LIMIT 1

SELECT * FROM biz_practical_ai_job
WHERE teacher_user_id=#{teacherUserId} AND lesson_id=#{lessonId} AND question_id=#{questionId}
  AND entry_year=#{entryYear} AND class_code=#{classCode}
ORDER BY job_id DESC LIMIT 1

mapper.update:
UPDATE biz_practical_ai_result SET result_status=#{resultStatus},suggested_score=#{suggestedScore},
  scoring_details_json=#{scoringDetailsJson,jdbcType=VARCHAR},evidence_json=#{evidenceJson,jdbcType=VARCHAR},
  confidence=#{confidence},provider_request_id=#{providerRequestId},prompt_tokens=#{promptTokens},
  completion_tokens=#{completionTokens},error_message=#{errorMessage},finish_time=#{finishTime}
WHERE result_id=#{resultId} AND practical_version_id=#{practicalVersionId}

UPDATE biz_practical_ai_result
SET apply_status=#{applyStatus}, applied_by_user_id=#{appliedByUserId,jdbcType=BIGINT},
    applied_time=#{appliedTime,jdbcType=TIMESTAMP}
WHERE result_id=#{resultId}

